     "summary": "9月18日，娃哈哈微博发布关于虎林公司员工住房公积金事宜的说明： 近期，虎林公司员工住房公积金问题引发广泛关注，我们深表歉意。保障员工合法权益是我们的责任和底线，我们诚恳接受批评，绝不推诿。 公司高度重视，第一时间开展核查，依法依规推进相关补缴事宜。目前，相关款项已划入鸡西市住房公积金管理中心指定账户，正配合办理逐人入账手续，确保尽快落实到每一位员工。 此次事件反映出我们对各历史...",
